// Fail-closed auth, same contract as every other VIO webhook. This one matters more than most:
// VIO-source-leads only leaks a prospect list, but THIS endpoint spends money. An unauthenticated
// caller could drain the Apollo credit balance with a single loop, and no gate further down would
// stop it, because every gate after this point is about lead quality rather than authorisation.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// The spending gate. Everything downstream of this node costs Apollo lead credits, so this is the
// last place a mistake is free.
//
// It takes an EXPLICIT LIST OF PERSON IDS, never a set of search filters. That is the whole design:
// a caller cannot say "reveal everyone matching director in Virginia" and discover afterwards that
// it meant nine thousand people. They must first run the free search (VIO-source-leads), look at
// who came back, and name the ones they want. Search wide for free; reveal narrow and on purpose.
const MAX_IDS = 25;                       // same ceiling as the free search's per_page
const PRODUCTS = ['oryoniq', 'visioneerit'];
const ID_RE = /^[A-Za-z0-9_-]{8,64}$/;    // Apollo person ids are opaque; shape-check only

const body = $input.first().json || {};

// Same string-only rule as VIO-source-leads and VIO-sendr-generate-page: a gate that coerces its
// input is not a gate. String(['oryoniq']) === 'oryoniq'.
if (typeof body.product !== 'string') {
  throw new Error(`REFUSED: 'product' must be a string, got ${Array.isArray(body.product) ? 'array' : typeof body.product}`);
}
const product = body.product.trim().toLowerCase();
if (PRODUCTS.indexOf(product) === -1) {
  throw new Error(`REFUSED: unknown product '${body.product}'. Known: ${PRODUCTS.join(', ')}`);
}

const raw = body.ids ?? body.apollo_ids;
if (!Array.isArray(raw)) {
  throw new Error(`REFUSED: 'ids' must be an array of Apollo person ids, got ${raw === undefined ? 'nothing' : typeof raw}`);
}
if (raw.length === 0) {
  throw new Error('REFUSED: no ids to reveal. An empty pull is a mistake, not a no-op — say what you want revealed.');
}
if (raw.length > MAX_IDS) {
  throw new Error(`REFUSED: ${raw.length} ids in one pull; the cap is ${MAX_IDS}. This cap is what stands between one wide search and an empty credit balance.`);
}

// De-duplicate rather than refuse: the same person can legitimately appear twice in a list a human
// assembled from two pages, and paying twice for one address is the failure worth preventing.
const seen = new Set();
const ids = [];
for (const v of raw) {
  const id = String(v == null ? '' : v).trim();
  if (!ID_RE.test(id)) {
    throw new Error(`REFUSED: '${id}' is not a plausible Apollo person id. Ids come from the free search — do not hand-type them.`);
  }
  if (seen.has(id)) continue;
  seen.add(id);
  ids.push(id);
}

// One n8n item per id. Every node downstream is per-item or $input.all(), so an array riding on a
// single item would silently reveal only the first person and report success for all of them.
return ids.map((apollo_id) => ({ json: {
  apollo_id,
  product,
  source_config: product,
  requested_count: raw.length,
  unique_count: ids.length,
  duplicates_collapsed: raw.length - ids.length,
  requested_by: String(body.requested_by || '').slice(0, 120),
} }));

// Drop anyone we already hold, BEFORE paying to reveal them.
//
// VIO-intake-verify-curate already de-duplicates, and it is the authority — but it runs AFTER the
// credit is spent. Intake's dedupe protects the Leads tab from double rows; this one protects the
// credit balance. They are different jobs and both are needed.
//
// Matching is on the Apollo person id only. That is deliberate and it is a KNOWN PARTIAL: a person
// we hold under a different id, or one typed in by hand from the same company, will not be caught
// here and will cost a credit before intake catches them by email. Matching on anything else is
// impossible at this point in the chain — we have not bought the address yet, so the id is the only
// identifier that exists.
//
// `lead_id` is checked as well as `apollo_id` because Leads.lead_id IS the Apollo id whenever the
// lead came from Apollo (see Normalize Lead in VIO-intake-verify-curate), and older rows written by
// reach-engine populate one column but not always the other.
const requested = $('Guard (cap + shape)').all().map((i) => i.json);

const held = new Set();
for (const item of $input.all()) {
  const r = item.json || {};
  for (const v of [r.apollo_id, r.lead_id]) {
    const s = String(v == null ? '' : v).trim();
    if (s) held.add(s);
  }
}

const toReveal = requested.filter((r) => !held.has(r.apollo_id));
const skipped  = requested.filter((r) => held.has(r.apollo_id)).map((r) => r.apollo_id);

// ALWAYS emit at least one item. A node that emits zero stops the chain where it stands, and the
// terminal report never runs — so "every one of them was already in the pipeline", which is a
// perfectly ordinary outcome, would have looked identical to a crash. This is the same trap that
// made VIO-sheet-provision silently do nothing for two runs while reporting success.
if (toReveal.length === 0) {
  return [{ json: {
    _reveal: false,
    product: requested.length ? requested[0].product : '',
    source_config: requested.length ? requested[0].source_config : '',
    already_held: skipped,
    already_held_count: skipped.length,
    to_reveal_count: 0,
  } }];
}

return toReveal.map((r) => ({ json: {
  _reveal: true,
  apollo_id: r.apollo_id,
  product: r.product,
  source_config: r.source_config,
  already_held: skipped,
  already_held_count: skipped.length,
  to_reveal_count: toReveal.length,
} }));

// Turn Apollo's people/match responses into the payload VIO-intake-verify-curate expects.
//
// The field list is not free-form. `Normalize Lead` inside intake builds an EXPLICIT object, so
// anything not named there is silently dropped — that is exactly how `Product` reached intake from
// VIO-inbox-mapper on 2026-08-29 and vanished before the Leads row was written. The names below
// match that node's inputs deliberately; adding a field here without adding it there does nothing.
//
// WHY THE REVEAL IS WORTH MORE THAN THE ADDRESS: the free search returns no surname and no company
// domain. people/match returns both. `company_domain` is what drives Sendr's dynamic-website GIF,
// so a lead pulled this way gets a personalised page, where a lead hand-typed without a website
// silently degrades to a generic preview.
const requested = $('Skip ones we already hold').all().map((i) => i.json).filter((j) => j._reveal);

const clean = (v, cap) => String(v == null ? '' : v)
  .replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap);

const normDomain = (v) => clean(v, 160).toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];

// Apollo's people/match does NOT fail on an id it cannot find. Proven live 2026-09-05: a request
// for id 000000000000000000000000 came back 200 with a DIFFERENT person on it. So "the call
// succeeded" says nothing about who was returned, and if that person had happened to carry an
// email we would have put a stranger nobody chose into an outbound pipeline and billed a credit
// for the privilege.
//
// Every response is therefore checked against the set of ids we actually asked for. A mismatch is
// treated as a failed reveal, never as a lead.
const requestedIds = new Set(requested.map((r) => r.apollo_id));

const responses = $input.all();

const rows = [];
responses.forEach((item, i) => {
  const j = item.json || {};
  const person = j.person || {};
  // Trust the id Apollo echoed back over positional alignment; fall back to position only when the
  // call failed outright and there is no person to read an id from.
  const echoed = clean(person.id, 64);
  const req = (echoed && requested.filter((r) => r.apollo_id === echoed)[0]) || requested[i] || {};
  // Report it under the id WE asked for, so the operator can see which of their picks failed.
  const apollo_id = (echoed && requestedIds.has(echoed)) ? echoed : clean(req.apollo_id, 64);

  // onError:continueRegularOutput means a failed call arrives here as an item carrying `error`
  // rather than killing the batch. One bad id must not cost us the other twenty-four.
  const mismatched = Boolean(echoed) && !requestedIds.has(echoed);
  const failed = Boolean(j.error) || mismatched || (!person.id && !person.email);
  const org = person.organization || person.account || {};
  // A substituted person's details are DISCARDED, not merely unused. Carrying the address forward
  // would write a stranger's email into the Events audit log under our outreach, and the whole
  // point of rejecting the substitution is that we have no business holding their details at all.
  const email = mismatched ? '' : clean(person.email, 160).toLowerCase();

  rows.push({
    apollo_id,
    ok: !failed && Boolean(email),
    reason: mismatched ? `apollo returned a DIFFERENT person (${echoed}) than the one requested — discarded`
          : Boolean(j.error) || (!person.id && !person.email) ? 'apollo did not return a person'
          : (email ? '' : 'apollo returned the person but no email address'),
    // --- the intake contract ---
    email,
    contact_email: email,
    first_name: mismatched ? '' : clean(person.first_name, 80),
    last_name: mismatched ? '' : clean(person.last_name, 80),
    title: mismatched ? '' : clean(person.title, 120),
    company: mismatched ? '' : clean(org.name || person.organization_name, 160),
    company_domain: mismatched ? '' : normDomain(org.primary_domain || org.website_url),
    linkedin_url: mismatched ? '' : clean(person.linkedin_url, 240),
    phone: '',                       // never requested here — direct-dial credits are the scarce ones
    has_email: Boolean(email),
    has_phone: false,
    source_config: clean(req.source_config, 40) || 'apollo',
    Product: (req.product === 'visioneerit') ? 'VisioneerIT' : 'OryonIQ',
  });
});

const usable = rows.filter((r) => r.ok);

// Always emit at least one item, for the same reason Skip does: "we paid and got nothing back" is a
// real outcome that must reach the report rather than stopping the chain silently.
if (usable.length === 0) {
  return [{ json: { _any: false, attempted: rows.length, usable: 0, rows } }];
}
return usable.map((r) => ({ json: Object.assign({ _any: true, _attempted: rows.length, _rows: rows }, r) }));

// One Events row per reveal ATTEMPT, not per usable lead.
//
// This is the only durable record that money was spent. Intake writes an Events row for each lead
// it verifies, but a credit spent on a person Apollo could not return an address for produces no
// lead, no intake row, and therefore no trace at all — the spend would exist only in Apollo's
// billing page and nobody would ever reconcile the two. "Who spent two hundred credits last
// Tuesday" has to be answerable from the sheet.
//
// est_cost_usd is left BLANK on purpose. SHEET_SCHEMA.md Tab 3: leave it blank while the real rate
// is unknown in COSTS.md — measure, don't estimate. A made-up number in the cost meter is worse
// than a gap, because a gap prompts someone to go and find the rate.
const first = $input.first().json || {};
const attempts = (first._any === false ? first.rows : first._rows) || [];
const now = new Date().toISOString();
const source = first.source_config || 'apollo';

// The reveal branch ran, so a call was made and something must be recorded. If it somehow produced
// no response items at all, that itself is the finding — writing nothing would leave the sheet
// implying no call happened, and this node emitting nothing would stop the chain before the report.
if (!attempts.length) {
  return [{ json: {
    timestamp: now, lead_id: '', lead_email: '',
    tool: 'apollo', action: 'reveal', units: 0, est_cost_usd: '',
    result: 'reveal branch ran but Apollo returned no response items',
    workflow: 'VIO-apollo-reveal', source_config: source,
  } }];
}

return attempts.map((r) => ({ json: {
  timestamp: now,
  lead_id: r.apollo_id || '',
  lead_email: r.email || '',
  tool: 'apollo',
  action: 'reveal',
  // Apollo bills a lead credit when it returns enrichment data. A call that came back with no
  // person and no address is recorded at 0 so the totals stay honest in both directions.
  units: r.ok ? 1 : 0,
  est_cost_usd: '',
  result: r.ok ? 'revealed work email' : (r.reason || 'no address returned'),
  workflow: 'VIO-apollo-reveal',
  source_config: r.source_config || source,
} }));

// Put the LEAD items back after the Events write.
//
// A Google Sheets node returns rows in the shape of the sheet it just wrote, so the items leaving
// `Log Reveal (Events)` carry Events columns — timestamp, tool, action — and no email address. If
// those flowed on to intake, intake would receive ten rows describing an audit log and try to
// verify them as people. That is not hypothetical: it is exactly how VIO-run-outreach broke on
// 2026-09-01, when VIO-enrol-email returned Events columns and `Shape row update` threw on every
// send.
//
// So the Events write is a SIDE BRANCH in sequence rather than a step in the data path, and this
// node reads the real payload back from the node that built it.
return $('Shape for intake').all();

// The single terminal. Every branch converges here, so this node's output IS the workflow's return
// value — for the webhook caller and for an Execute Workflow caller alike.
//
// One terminal is a rule, not a preference: n8n hands the caller whichever terminal node happened
// to finish last, so a workflow with two ends returns a coin flip. VIO-enrol-email and
// VIO-intake-verify-curate both shipped that bug and both were fixed the same way.
//
// It reads from NAMED NODES rather than from its input, because which branch fed it is exactly the
// thing being reported. Each read is wrapped: a node that never ran in this execution throws when
// referenced, and "the reveal branch did not run" is an answer, not a failure.
const scrub = (v) => Array.isArray(v) ? v.map(scrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]))
  : (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);

const read = (name) => { try { return $(name).all().map((i) => i.json); } catch (e) { return null; } };

const requested = read('Guard (cap + shape)') || [];
const skipStage = read('Skip ones we already hold') || [];
const shaped    = read('Shape for intake') || [];

const first = skipStage[0] || {};
const alreadyHeld = first.already_held || [];

// Attempts live on whichever shape the Shape node produced: the noop item carries `rows`, a normal
// item carries `_rows`.
const s0 = shaped[0] || {};
const attempts = (s0._any === false ? s0.rows : s0._rows) || [];
const revealed = attempts.filter((r) => r.ok);
const noAddress = attempts.filter((r) => !r.ok);

// Per-lead verdicts from intake, when the batch got that far.
const intake = read('Verify + curate (intake)') || [];
const verdicts = [];
for (const r of intake) {
  const list = Array.isArray(r && r.results) ? r.results : (r && r.outcome ? [r] : []);
  for (const v of list) {
    verdicts.push({
      email: v.email || v.contact_email || '',
      outcome: v.outcome || '',
      reason: v.reason || '',
      reoon_status: v.reoon_status || '',
      lead_id: v.lead_id || '',
    });
  }
}

return [{ json: scrub({
  ok: true,
  workflow: 'VIO-apollo-reveal',
  ran: ['guard', 'dedupe_before_spending', attempts.length ? 'apollo_people_match' : null,
        attempts.length ? 'log_events' : null, revealed.length ? 'intake_verify_curate' : null]
       .filter(Boolean),

  requested: requested.length,
  duplicates_collapsed: (requested[0] || {}).duplicates_collapsed || 0,
  already_held: alreadyHeld.length,
  already_held_ids: alreadyHeld,

  reveal_calls: attempts.length,
  revealed: revealed.length,
  no_address: noAddress.length,
  no_address_ids: noAddress.map((r) => r.apollo_id),

  // Apollo bills a lead credit when it returns enrichment data, so a call that came back empty is
  // counted at zero. Called an estimate rather than a fact because the authority is Apollo's own
  // billing page, not this workflow — reconcile against it before quoting a spend to anyone.
  credits_spent_estimate: revealed.length,

  // What a caller most wants to know: these people are NOT emailed. They are queued behind the same
  // verification, de-duplication and suppression checks as a hand-typed lead, and then the daily cap
  // decides how many actually go out.
  handed_to_intake: revealed.length,
  verdicts,
  note: revealed.length
    ? 'Revealed addresses were handed to VIO-intake-verify-curate. Nothing has been emailed — '
      + 'intake verifies and de-duplicates, then VIO-run-outreach sends within the daily cap.'
    : 'No address was revealed, so nothing was handed on. No lead was created.',
}) }];
